int eggDrop(int n, int k) {
    std::vector<std::vector<int> > eggFloor(n + 1, std::vector<int>(k + 1));

    int result;

    for (int i = 1; i <= n; i++) {
        eggFloor[i][1] = 1;  
        eggFloor[i][0] = 0;  
    }

    for (int j = 1; j <= k; j++) {
        eggFloor[1][j] = j;
    }

    for (int i = 2; i <= n; i++) {
        for (int j = 2; j <= k; j++) {
            eggFloor[i][j] = INT_MAX;
            for (int x = 1; x <= j; x++) {

                result = 1 + max(eggFloor[i - 1][x - 1], eggFloor[i][j - x]);
                if (result < eggFloor[i][j])
                    eggFloor[i][j] = result;
            }
        }
    }

    return eggFloor[n][k];
}

