int InterpolationSearch(int A[], int n, int x) {
    int low = 0;
    int high = n - 1;
    while (low <= high) {
        int mid = low + (((high - 1) * (x - A[low])) / (A[high] - A[low]));
        if (x == A[mid])
            return mid;  
        else if (x < A[mid])
            high = mid - 1;  
        else
            low = mid + 1;  
    }

    return -1;
}

